{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Studies were eligible for inclusion if they (i) were original research articles, cohort studies, or case reports; (ii) focused on AI-driven tools used for assessing or improving mental health outcomes; and (iii) were published between 2000 and 2024. Studies were excluded if they (i) did not directly assess AI tools for mental health applications; (ii) were systematic reviews, meta-analyses, or other secondary sources (excluded to avoid duplication and focus on original data); (iii) lacked full-text availability; or (iv) were not published in English.",
      "reason": "The manuscript specifies the inclusion and exclusion criteria, including study designs (original research, cohort, case reports), the focus (AI-driven tools for mental health), and publication timeframe/language."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Studies were eligible for inclusion if they ... (iii) were published between 2000 and 2024. ... Studies were excluded if they ... (iv) were not published in English.",
      "reason": "The manuscript specifies the dissemination year range (2000-2024) and language (English) as eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "The full excluded if they contained missing or incomplete data, lacked AI-specific interventions, or failed to report on mental health outcomes. This led to the exclusion of 3 full-texts from PubMed, 2 from Elsevier, and 6 from Google Scholar.",
      "reason": "The text distinguishes between exclusion due to missing/incomplete data versus other reasons like lacking AI interventions or failing to report on mental health outcomes."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Meta-analysis was employed as the primary method for quantitatively synthesizing the results of the selected studies. This approach was chosen to estimate a pooled effect size for the impact of AI-based interventions on mental health outcomes... A total of six eligible studies involving 901 participants were included in the meta-analysis.",
      "reason": "The manuscript specifies the synthesis method (meta-analysis) and links it to the objective of estimating pooled effect sizes for AI-based interventions on mental health outcomes."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Studies were excluded if they ... (ii) were systematic reviews, meta-analyses, or other secondary sources (excluded to avoid duplication and focus on original data)",
      "reason": "The manuscript provides a rationale for excluding secondary sources (to avoid duplication and focus on original data)."
    }
  ],
  "confidence": 100
}

